SELECT Site.numsit,Site.nomsit,Site.typsit,Site.comsit,Site.adrsit,Site.codpossit,Site.vilsit,Site.nbrentsit,parametre.datdeb,parametre.datfin,parametre.datdeb,parametre.datfin,Client.nomcli FROM [Client],[Site],[parametre],[Intervention] WHERE (((Intervention.datintpre) Between parametre!datdeb And parametre!datfin And (Intervention.datintpre) Is Not Null) And ((Intervention.datint) Is Null) And ((Intervention.typint)="1")) 
